// ─────────────────────────────────────────────────────────────────────────────
// Resolve Trigger & Verify Webhook
// Scheduled and manual runs → mode "scan" (CRM Search for unenriched contacts).
// Webhook runs → mode "webhook": verify the HubSpot v3 signature, keep
// contact.creation and watched contact.propertyChange events, drop changes
// made by this integration (loop guard), and de-duplicate contact IDs.
//
// Security note: HUBSPOT_APP_CLIENT_SECRET is read here only because an HMAC
// cannot be computed in an HTTP header field. It never leaves this node.
// ─────────────────────────────────────────────────────────────────────────────
const req = $input.first().json;
const cfg = req.config;
const isWebhook = req.body !== undefined && req.headers !== undefined;

if (!isWebhook) return [{ json: { mode: 'scan', contactIds: [], forcedIds: [], counters: null, signature: 'n/a' } }];

// ── Signature (skipped only in sandbox) ──────────────────────────────────
const headers = Object.fromEntries(Object.entries(req.headers || {}).map(([k, v]) => [String(k).toLowerCase(), v]));
let signature = 'skipped (sandbox)';
if (!cfg.sandboxMode && cfg.requireSignature) {
  const sig = headers['x-hubspot-signature-v3'];
  const ts = headers['x-hubspot-request-timestamp'];
  if (!sig || !ts) throw new Error('Rejected: missing HubSpot v3 signature headers.');
  if (!Number.isFinite(Number(ts)) || Math.abs(Date.now() - Number(ts)) > 300000) throw new Error('Rejected: HubSpot request timestamp outside the 5-minute window.');
  let secret = '';
  try { secret = String($env.HUBSPOT_APP_CLIENT_SECRET || ''); } catch (e) { secret = ''; }
  if (!secret) throw new Error('Rejected: HUBSPOT_APP_CLIENT_SECRET is not set and REQUIRE_HUBSPOT_SIGNATURE is not false.');
  let crypto;
  try { crypto = require('crypto'); } catch (e) { throw new Error('Signature verification needs NODE_FUNCTION_ALLOW_BUILTIN=crypto.'); }
  const raw = typeof req.body === 'string' ? req.body : JSON.stringify(req.body);
  const expected = crypto.createHmac('sha256', secret).update(`POST${cfg.webhookPublicUrl || req.webhookUrl}${raw}${ts}`, 'utf8').digest('base64');
  const a = Buffer.from(String(sig));
  const b = Buffer.from(expected);
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) throw new Error('Rejected: HubSpot v3 signature mismatch.');
  signature = 'verified';
} else if (!cfg.sandboxMode) {
  signature = 'disabled (REQUIRE_HUBSPOT_SIGNATURE=false)';
}

// ── Events ────────────────────────────────────────────────────────────────
let events = req.body;
if (typeof events === 'string') { try { events = JSON.parse(events); } catch (e) { events = []; } }
if (!Array.isArray(events)) events = events ? [events] : [];

const counters = { received: events.length, ignoredType: 0, ignoredProperty: 0, selfInflicted: 0, duplicate: 0 };
const ids = new Set();
const forced = new Set();
for (const e of events) {
  const type = String(e?.subscriptionType || '');
  const id = String(e?.objectId ?? '');
  if (!/^\d+$/.test(id) || !['contact.creation', 'contact.propertyChange'].includes(type)) { counters.ignoredType += 1; continue; }
  // Loop guard first: changes written by this integration never re-trigger enrichment.
  if (cfg.hubspotAppId && String(e.sourceId || '') === cfg.hubspotAppId) { counters.selfInflicted += 1; continue; }
  if (type === 'contact.propertyChange' && !cfg.watchProperties.includes(String(e.propertyName))) { counters.ignoredProperty += 1; continue; }
  if (ids.has(id)) counters.duplicate += 1;
  ids.add(id);
  // A changed profile URL forces re-verification even inside the recheck window.
  if (type === 'contact.propertyChange' && e.propertyName === cfg.linkedinUrlProperty) forced.add(id);
}

return [{ json: { mode: 'webhook', contactIds: [...ids].slice(0, cfg.maxContactsPerRun), forcedIds: [...forced], counters, signature } }];

// ─────────────────────────────────────────────────────────────────────────────
// Mock Contact Retrieval (SANDBOX_MODE=true)
// Returns fictitious contacts in the CRM Search / batch-read response shape.
// In webhook mode only the requested IDs are returned. Each contact exercises
// one path: update, job change, empty-payload protection, personal email
// without a profile URL, not found, identity mismatch, opt-out, low
// confidence, and an invalid avatar URL.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const ctx = $input.first().json;
const DAY_MS = 24 * 60 * 60 * 1000;
const ago = (d) => new Date(Date.now() - d * DAY_MS).toISOString();
const L = cfg.linkedinUrlProperty;

const base = {
  firstname: null, lastname: null, email: null, jobtitle: null, company: null, lifecyclestage: 'lead', [L]: null,
  social_profile_status: null, social_profile_id: null, social_avatar_url: null, social_headline: null,
  social_current_title: null, social_current_company: null, social_current_company_domain: null,
  social_employment_history_json: null, social_enrichment_last_checked_at: null, social_enrichment_opt_out: null,
};
const c = (id, p) => ({ id, properties: { hs_object_id: id, createdate: ago(30), ...base, ...p } });

const catalog = [
  c('8100000001', { firstname: 'Alex', lastname: 'Mercer', email: 'alex@company.example', jobtitle: 'Director of Operations', company: 'Company Example Ltd', [L]: 'https://www.social-graph.example/in/alex-mercer-syn' }),
  c('8100000002', { firstname: 'Priya', lastname: 'Natarajan', email: 'priya@northbeam.example', jobtitle: 'VP Marketing', company: 'Northbeam Example', lifecyclestage: 'salesqualifiedlead',
    social_profile_status: 'active', social_current_title: 'VP Marketing', social_current_company: 'Northbeam Example', social_current_company_domain: 'northbeam.example', social_enrichment_last_checked_at: ago(45) }),
  c('8100000003', { firstname: 'Jordan', lastname: 'Ellis', email: 'jordan@company.example', [L]: 'https://www.social-graph.example/in/jordan-ellis-syn',
    social_profile_status: 'active', social_avatar_url: 'https://media.social-graph.example/avatars/jordan-ellis-syn.jpg', social_headline: 'Head of Finance',
    social_current_title: 'Head of Finance', social_current_company: 'Company Example Ltd', social_current_company_domain: 'company.example',
    social_employment_history_json: JSON.stringify([{ title: 'Head of Finance', company: 'Company Example Ltd', domain: 'company.example', start: '2023-02', end: null, current: true }]),
    social_enrichment_last_checked_at: ago(40) }),
  c('8100000004', { firstname: 'Sam', lastname: 'Okafor', email: 'sam.okafor@personal-mail.example' }),
  c('8100000005', { firstname: 'Riley', lastname: 'Chen', email: 'riley@company.example' }),
  c('8100000006', { firstname: 'Morgan', lastname: 'Blake', email: 'morgan@company.example', [L]: 'https://www.social-graph.example/in/morgan-blake-syn' }),
  c('8100000007', { firstname: 'Casey', lastname: 'Novak', email: 'casey@company.example', social_enrichment_opt_out: 'true' }),
  c('8100000008', { firstname: 'Taylor', lastname: 'Brooks', email: 'taylor@company.example' }),
  c('8100000009', { firstname: 'Avery', lastname: 'Quinn', email: 'avery@company.example', [L]: 'https://www.social-graph.example/in/avery-quinn-syn' }),
];

const results = ctx.mode === 'webhook' ? catalog.filter((x) => ctx.contactIds.includes(x.id)) : catalog;
return [{ json: { source: 'synthetic-fixtures', results } }];

// ─────────────────────────────────────────────────────────────────────────────
// Build Contact Search Request
// Scan mode: contacts never checked, or last checked more than RESCAN_DAYS
// ago, optionally limited to TARGET_LIFECYCLE_STAGES. Newest contacts first.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const DAY_MS = 24 * 60 * 60 * 1000;
const lifecycle = cfg.targetLifecycleStages.length ? [{ propertyName: 'lifecyclestage', operator: 'IN', values: cfg.targetLifecycleStages }] : [];

return [{
  json: {
    searchBody: {
      filterGroups: [
        { filters: [{ propertyName: 'social_enrichment_last_checked_at', operator: 'NOT_HAS_PROPERTY' }, ...lifecycle] },
        { filters: [{ propertyName: 'social_enrichment_last_checked_at', operator: 'LT', value: String(Date.now() - cfg.rescanDays * DAY_MS) }, ...lifecycle] },
      ],
      properties: cfg.contactProperties,
      sorts: [{ propertyName: 'createdate', direction: 'DESCENDING' }],
      limit: 100,
    },
  },
}];

// ─────────────────────────────────────────────────────────────────────────────
// Select Contacts for Enrichment
// Accepts CRM Search pages, a batch-read response or the sandbox snapshot,
// then applies the eligibility rules: opt-out, usable identifier, personal
// email minimisation, webhook recheck window, de-duplication and run cap.
// Emits one item per contact with the enrichment request body prepared.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const ctx = $('Resolve Trigger & Verify Webhook').first().json;
const HOUR_MS = 60 * 60 * 1000;
const L = cfg.linkedinUrlProperty;

const PERSONAL = ['gmail.com', 'googlemail.com', 'yahoo.com', 'outlook.com', 'hotmail.com', 'live.com', 'icloud.com', 'me.com', 'aol.com', 'proton.me', 'protonmail.com', 'gmx.com', 'gmx.de', 'yandex.com', 'mail.com', 'zoho.com', 'qq.com', ...cfg.extraPersonalEmailDomains];
// The synthetic fixture domain is treated as personal in sandbox and manual test runs only.
if (cfg.sandboxMode || cfg.executionMode !== 'production') PERSONAL.push('personal-mail.example');

const emailDomain = (e) => (String(e || '').toLowerCase().split('@')[1] || '').trim();
function normProfileUrl(u) {
  try {
    const url = new URL(String(u).trim());
    if (url.protocol !== 'https:' && url.protocol !== 'http:') return null;
    return `https://${url.hostname.replace(/^www\./, '').toLowerCase()}${url.pathname.replace(/\/+$/, '').toLowerCase()}`;
  } catch (e) {
    return null;
  }
}

const raw = [];
for (const item of $input.all()) for (const r of Array.isArray(item.json.results) ? item.json.results : []) raw.push(r);

const stats = { mode: ctx.mode, retrieved: raw.length, optedOut: 0, noIdentifier: 0, personalEmailWithheld: 0, recentlyChecked: 0, duplicate: 0, overCap: 0, selected: 0 };
const seen = new Set();
const selected = [];

for (const r of raw) {
  const id = String(r.id);
  const p = r.properties || {};
  if (seen.has(id)) { stats.duplicate += 1; continue; }
  seen.add(id);
  if (String(p.social_enrichment_opt_out).toLowerCase() === 'true') { stats.optedOut += 1; continue; }

  const checkedMs = Date.parse(p.social_enrichment_last_checked_at || '');
  if (ctx.mode === 'webhook' && !ctx.forcedIds.includes(id) && Number.isFinite(checkedMs) && Date.now() - checkedMs < cfg.minRecheckHours * HOUR_MS) {
    stats.recentlyChecked += 1;
    continue;
  }

  const profileUrl = p[L] ? normProfileUrl(p[L]) : null;
  const domain = emailDomain(p.email);
  const personal = domain && PERSONAL.some((d) => domain === d || domain.endsWith(`.${d}`));
  const workEmail = p.email && !personal ? String(p.email).trim().toLowerCase() : null;
  if (personal && !cfg.sendPersonalEmails) stats.personalEmailWithheld += 1;
  const emailToSend = workEmail || (personal && cfg.sendPersonalEmails ? String(p.email).trim().toLowerCase() : null);

  if (!profileUrl && !emailToSend) { stats.noIdentifier += 1; continue; }
  if (selected.length >= cfg.maxContactsPerRun) { stats.overCap += 1; continue; }

  selected.push({
    contactId: id,
    existing: p,
    identity: { firstName: p.firstname || null, lastName: p.lastname || null, profileUrl },
    requestBody: {
      profile_url: profileUrl,
      email: emailToSend,
      first_name: p.firstname || null,
      last_name: p.lastname || null,
      company_domain: workEmail ? domain : null,
      fields: ['profile', 'avatar', 'current_position', 'positions'],
    },
  });
}
stats.selected = selected.length;

if (!selected.length) return [{ json: { contactId: null, skipReason: 'No eligible contacts.', stats } }];
return selected.map((s) => ({ json: { ...s, selectStats: stats } }));

// ─────────────────────────────────────────────────────────────────────────────
// Attach Provider Responses
// The HTTP node runs with "continue on error" and full responses, so each
// output item holds { statusCode, body } or { error }. Items align by index
// with the contacts sent to the provider.
// ─────────────────────────────────────────────────────────────────────────────
const contacts = $('Enrichment Live?').all();
const responses = $input.all();
// Integrity guard: a count mismatch could attach one person's profile to another contact.
if (responses.length !== contacts.length) {
  throw new Error(`Provider returned ${responses.length} responses for ${contacts.length} contacts; refusing to attach profiles. If pinned data is in use, unpin "Social Graph: Lookup Profile" or align its items.`);
}

return responses.map((item, i) => {
  const base = contacts[i] ? contacts[i].json : {};
  const j = item.json || {};
  let httpStatus = Number(j.statusCode) || null;
  let error = null;
  if (j.error) {
    const msg = String(j.error.message || j.error);
    const m = /\b(4\d\d|5\d\d)\b/.exec(msg);
    httpStatus = httpStatus || (m ? Number(m[1]) : null);
    error = msg.slice(0, 300);
  }
  const body = j.body !== undefined ? j.body : (j.error ? null : j);
  return { json: { ...base, provider: { httpStatus: httpStatus || (body ? 200 : null), error, body } } };
});

// ─────────────────────────────────────────────────────────────────────────────
// Mock Social Graph (SANDBOX_MODE=true or ENRICHMENT_MODE=mock)
// Returns fictitious provider responses in the documented contract shape,
// keyed by the synthetic contact's email, then attaches them exactly as the
// live Attach node does. No data leaves the n8n instance.
// ─────────────────────────────────────────────────────────────────────────────
const pos = (title, company, domain, start, end = null) => ({ title, company_name: company, company_domain: domain, start_date: start, end_date: end, is_current: end === null });
const profile = (id, first, last, p) => ({
  match: { status: 'matched', confidence: 0.94, matched_on: ['profile_url', 'email'] },
  profile: {
    id, public_url: `https://www.social-graph.example/in/${first.toLowerCase()}-${last.toLowerCase()}-syn`, active: true,
    first_name: first, last_name: last, headline: null, avatar_url: null, current_position: null, positions: [], ...p,
  },
});

const RESPONSES = {
  'alex@company.example': profile('sg-syn-0001', 'Alex', 'Mercer', {
    headline: 'Director of Operations · Supply chain automation',
    avatar_url: 'https://media.social-graph.example/avatars/alex-mercer-syn.jpg',
    current_position: pos('Director of Operations', 'Company Example Ltd', 'company.example', '2022-04'),
    positions: [pos('Director of Operations', 'Company Example Ltd', 'company.example', '2022-04'), pos('Operations Manager', 'Harborline Example', 'harborline.example', '2018-09', '2022-03'), pos('Analyst', 'Brightpath Example', 'brightpath.example', '2016-06', '2018-08')],
  }),
  'priya@northbeam.example': profile('sg-syn-0002', 'Priya', 'Natarajan', {
    headline: 'CMO at Lumen Grid Example',
    avatar_url: 'https://media.social-graph.example/avatars/priya-natarajan-syn.jpg',
    current_position: pos('Chief Marketing Officer', 'Lumen Grid Example', 'lumengrid.example', '2026-10'),
    positions: [pos('Chief Marketing Officer', 'Lumen Grid Example', 'lumengrid.example', '2026-10'), pos('VP Marketing', 'Northbeam Example', 'northbeam.example', '2021-01', '2026-09')],
  }),
  // Provider returns an active profile with no avatar and no positions: existing HubSpot values must survive.
  'jordan@company.example': profile('sg-syn-0003', 'Jordan', 'Ellis', { headline: '', avatar_url: '', current_position: null, positions: [] }),
  'riley@company.example': { match: { status: 'not_found', confidence: 0, matched_on: [] }, profile: null },
  // Profile URL in HubSpot points to a different profile than the provider returned.
  'morgan@company.example': { match: { status: 'matched', confidence: 0.91, matched_on: ['email'] }, profile: { id: 'sg-syn-0006', public_url: 'https://www.social-graph.example/in/morgan-blake-other-syn', active: true, first_name: 'Morgan', last_name: 'Blake', headline: 'Consultant', avatar_url: 'https://media.social-graph.example/avatars/other.jpg', positions: [] } },
  'taylor@company.example': { match: { status: 'ambiguous', confidence: 0.55, matched_on: ['name'] }, profile: { id: 'sg-syn-0008', public_url: 'https://www.social-graph.example/in/taylor-brooks-42-syn', active: true, first_name: 'Taylor', last_name: 'Brooks', positions: [] } },
  'avery@company.example': profile('sg-syn-0009', 'Avery', 'Quinn', {
    headline: 'Platform Engineer',
    avatar_url: 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk',
    current_position: pos('Platform Engineer', 'Company Example Ltd', 'company.example', '2024-01'),
    positions: [pos('Platform Engineer', 'Company Example Ltd', 'company.example', '2024-01')],
  }),
};

return $input.all().map((item) => {
  const body = RESPONSES[item.json.requestBody.email] || { match: { status: 'not_found', confidence: 0, matched_on: [] }, profile: null };
  return { json: { ...item.json, provider: { httpStatus: body.match.status === 'not_found' ? 404 : 200, error: null, body }, mock: true } };
});

// ─────────────────────────────────────────────────────────────────────────────
// Normalize & Diff Evaluator
// Parses each provider response, enforces identity checks, validates the
// avatar URL and employment history, and diffs against existing HubSpot
// values. Empty or invalid incoming values never overwrite valid existing
// data. Every processed contact gets a status and checked timestamp so the
// scan cursor advances.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const nowIso = new Date().toISOString();
const L = cfg.linkedinUrlProperty;

const blank = (v) => v === null || v === undefined || String(v).trim() === '';
const clean = (v, max) => (blank(v) ? null : String(v).replace(/[\u0000-\u001F\u007F]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max));
const ym = (v) => {
  if (blank(v)) return null;
  const m = /^(\d{4})(?:-(\d{1,2}))?/.exec(String(v));
  if (!m) return null;
  const year = Number(m[1]);
  if (year < 1950 || year > new Date().getUTCFullYear() + 1) return null;
  return m[2] ? `${m[1]}-${String(Math.min(12, Math.max(1, Number(m[2])))).padStart(2, '0')}` : m[1];
};
const normDomain = (d) => {
  const s = String(d || '').trim().toLowerCase().replace(/^[a-z]+:\/\//, '').split(/[/?#]/)[0].replace(/^www\./, '');
  return /^(?=.{4,253}$)(?:[a-z0-9-]{1,63}\.)+[a-z]{2,63}$/.test(s) ? s : null;
};
const normProfileUrl = (u) => {
  try {
    const url = new URL(String(u).trim());
    return `https://${url.hostname.replace(/^www\./, '').toLowerCase()}${url.pathname.replace(/\/+$/, '').toLowerCase()}`;
  } catch (e) { return null; }
};
const normName = (s) => String(s || '').normalize('NFKD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z]/g, '');

function validAvatar(u) {
  if (blank(u)) return { ok: false, reason: 'empty' };
  const s = String(u).trim();
  if (s.length > 1000) return { ok: false, reason: 'too_long' };
  let url;
  try { url = new URL(s); } catch (e) { return { ok: false, reason: 'not_a_url' }; }
  if (url.protocol !== 'https:') return { ok: false, reason: 'not_https' };
  if (url.username || url.password) return { ok: false, reason: 'credentials_in_url' };
  if (cfg.allowedAvatarHosts.length && !cfg.allowedAvatarHosts.some((h) => url.hostname === h || url.hostname.endsWith(`.${h}`))) return { ok: false, reason: 'host_not_allowed' };
  if (/\.(svg|html?|js)(\?|$)/i.test(url.pathname)) return { ok: false, reason: 'unsafe_extension' };
  return { ok: true, value: url.toString() };
}

function normPositions(list) {
  const out = [];
  for (const p of Array.isArray(list) ? list : []) {
    const title = clean(p.title || p.job_title, 120);
    const company = clean(p.company_name || p.company || p.organization, 120);
    if (!title && !company) continue;
    const start = ym(p.start_date || p.start);
    const end = ym(p.end_date || p.end);
    out.push({ title, company, domain: normDomain(p.company_domain || p.domain), start, end: end || null, current: p.is_current === true || (!end && p.is_current !== false) });
  }
  out.sort((a, b) => (b.current - a.current) || String(b.start || '').localeCompare(String(a.start || '')));
  const seen = new Set();
  return out.filter((p) => { const k = `${p.title}|${p.company}|${p.start}`; if (seen.has(k)) return false; seen.add(k); return true; }).slice(0, cfg.employmentHistoryMax);
}

const stableHistory = (json) => {
  if (blank(json)) return null;
  try { return JSON.stringify(normPositions(JSON.parse(json).map((p) => ({ ...p, company_name: p.company, company_domain: p.domain, start_date: p.start, end_date: p.end, is_current: p.current })))); } catch (e) { return null; }
};

const stats = { processed: 0, matched: 0, notFound: 0, ambiguous: 0, mismatch: 0, inactive: 0, errors: 0, contactsChanged: 0, fieldsWritten: 0, fieldsProtected: 0, avatarsRejected: 0, jobChanges: 0, standardFieldsFilled: 0 };
const results = [];

for (const item of $input.all()) {
  const c = item.json;
  const ex = c.existing || {};
  stats.processed += 1;
  const prov = c.provider || {};
  const body = prov.body || {};
  const match = body.match || body.meta || {};
  const pr = body.profile || body.person || body.data || null;
  const confidence = Number(match.confidence ?? match.score ?? 0);

  // ── Status decision ───────────────────────────────────────────────────
  let status;
  let reason = null;
  if (prov.error && prov.httpStatus !== 404) { status = 'error'; reason = prov.error; }
  else if (prov.httpStatus === 404 || String(match.status) === 'not_found' || !pr) status = 'not_found';
  else if (String(match.status) === 'ambiguous' || confidence < cfg.minMatchConfidence) { status = 'ambiguous'; reason = `confidence ${confidence}`; }
  else {
    const expectedUrl = c.identity.profileUrl;
    const gotUrl = pr.public_url ? normProfileUrl(pr.public_url) : null;
    const lastOk = !c.identity.lastName || !pr.last_name || normName(c.identity.lastName) === normName(pr.last_name);
    const firstOk = !c.identity.firstName || !pr.first_name || normName(pr.first_name).startsWith(normName(c.identity.firstName).slice(0, 3));
    if (expectedUrl && gotUrl && expectedUrl !== gotUrl) { status = 'mismatch'; reason = 'profile_url_differs'; }
    else if (!lastOk || !firstOk) { status = 'mismatch'; reason = 'name_differs'; }
    else status = pr.active === false ? 'inactive' : 'active';
  }

  // ── Candidate values (only for verified identities) ─────────────────────
  const candidate = {};
  const notes = [];
  let jobChange = null;
  if (status === 'active' || status === 'inactive') {
    candidate.social_profile_id = clean(pr.id, 100);
    candidate[L] = pr.public_url ? normProfileUrl(pr.public_url) : null;
    candidate.social_headline = clean(pr.headline, 250);
    const av = validAvatar(pr.avatar_url || pr.photo_url);
    if (av.ok) candidate.social_avatar_url = av.value;
    else { candidate.social_avatar_url = null; if (av.reason !== 'empty') { notes.push(`avatar_rejected:${av.reason}`); stats.avatarsRejected += 1; } }

    const positions = normPositions(pr.positions || pr.experience || []);
    const current = normPositions([pr.current_position].filter(Boolean))[0] || positions.find((p) => p.current) || null;
    candidate.social_current_title = current?.title || null;
    candidate.social_current_company = current?.company || null;
    candidate.social_current_company_domain = current?.domain || null;
    candidate.social_employment_history_json = positions.length ? JSON.stringify(positions) : null;

    const prevDomain = normDomain(ex.social_current_company_domain);
    if (current?.domain && prevDomain && current.domain !== prevDomain) {
      jobChange = { from: ex.social_current_company || prevDomain, to: current.company || current.domain };
      stats.jobChanges += 1;
    }
  }

  // ── Diff with protection ───────────────────────────────────────────────
  const properties = {};
  const protectedFields = [];
  for (const [k, v] of Object.entries(candidate)) {
    const old = ex[k];
    if (blank(v)) { if (!blank(old)) protectedFields.push(k); continue; }
    // A profile URL a person entered is never rewritten; it is only filled when empty.
    if (k === L) { if (blank(old)) properties[k] = v; continue; }
    const same = k === 'social_employment_history_json' ? stableHistory(old) === v : String(old ?? '') === String(v);
    if (!same) properties[k] = v;
  }

  // Standard HubSpot fields: never blanked; policy controls filling or overwriting.
  if ((status === 'active') && cfg.standardFieldPolicy !== 'never') {
    for (const [std, src] of [['jobtitle', candidate.social_current_title], ['company', candidate.social_current_company]]) {
      if (blank(src)) continue;
      if (blank(ex[std]) || (cfg.standardFieldPolicy === 'overwrite' && String(ex[std]) !== src)) { properties[std] = src; stats.standardFieldsFilled += 1; }
    }
  }

  const contentChanged = Object.keys(properties).length > 0;
  properties.social_profile_status = status;
  properties.social_enrichment_last_checked_at = nowIso;
  if (status === 'active' || status === 'inactive') properties.social_enrichment_confidence = String(Math.round(confidence * 100) / 100);
  if (jobChange) properties.social_job_change_detected_at = nowIso;

  stats[{ active: 'matched', inactive: 'inactive', not_found: 'notFound', ambiguous: 'ambiguous', mismatch: 'mismatch', error: 'errors' }[status]] += 1;
  if (status === 'inactive') stats.matched += 1;
  if (contentChanged) stats.contactsChanged += 1;
  stats.fieldsProtected += protectedFields.length;

  const changedFields = Object.keys(properties).filter((k) => !['social_profile_status', 'social_enrichment_last_checked_at', 'social_enrichment_confidence', 'social_job_change_detected_at'].includes(k));
  stats.fieldsWritten += changedFields.length;

  results.push({
    contactId: c.contactId,
    status,
    reason,
    confidence,
    contentChanged,
    changedFields,
    protectedFields,
    jobChange,
    notes,
    // Errors are not written: the contact is retried on the next run.
    update: status === 'error' ? null : { id: c.contactId, properties },
  });
}

return [{ json: { stats, results } }];

// ─────────────────────────────────────────────────────────────────────────────
// Compose Update Batches & Run Stats
// Chunks contact updates into HubSpot batch-sized groups (≤ 100) and
// assembles the execution stats logged at the end of every run.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const ctx = $('Resolve Trigger & Verify Webhook').first().json;
const select = $('Select Contacts for Enrichment').first().json.selectStats || {};
const { stats, results } = $input.first().json;

const updates = results.map((r) => r.update).filter(Boolean);
const size = Math.min(100, cfg.hubspotBatchSize);
const batches = [];
for (let i = 0; i < updates.length; i += size) batches.push(updates.slice(i, i + size));

const errorRate = stats.processed ? Math.round((stats.errors / stats.processed) * 1000) / 10 : 0;
const breakerReasons = [];
if (stats.processed >= 10 && errorRate > cfg.maxProviderErrorPct) breakerReasons.push(`provider error rate ${errorRate}% exceeds MAX_PROVIDER_ERROR_PCT (${cfg.maxProviderErrorPct}%)`);

return [{
  json: {
    dryRun: cfg.dryRun,
    syncToHubspot: cfg.syncToHubspot && breakerReasons.length === 0,
    circuitBreaker: { open: breakerReasons.length > 0, reasons: breakerReasons },
    counts: { updates: updates.length, batches: batches.length },
    updateBatches: batches,
    runStats: {
      runId: cfg.runId,
      mode: ctx.mode,
      signature: ctx.signature,
      webhookCounters: ctx.counters,
      sandbox: cfg.sandboxMode,
      enrichment: cfg.enrichmentLive ? 'live' : 'mock',
      selection: select,
      enrichmentStats: { ...stats, errorRate },
      jobChanges: results.filter((r) => r.jobChange).map((r) => ({ contactId: r.contactId, ...r.jobChange })),
    },
    results: results.map(({ update, ...r }) => r),
  },
}];

// ─────────────────────────────────────────────────────────────────────────────
// Log Run Stats
// Final node on every path. Emits one structured summary item and writes it to
// the n8n log (console), so execution history doubles as an enrichment audit.
// ─────────────────────────────────────────────────────────────────────────────
const composed = $('Compose Update Batches & Run Stats').first().json;
let writes = { batches: 0, written: 0, errors: 0 };
try {
  const responses = $('HubSpot: Batch Update Contacts').all().map((i) => i.json);
  writes = {
    batches: responses.length,
    written: responses.reduce((n, r) => n + (Array.isArray(r.results) ? r.results.length : 0), 0),
    errors: responses.reduce((n, r) => n + (Array.isArray(r.errors) ? r.errors.length : 0), 0),
  };
} catch (e) { /* batch update did not run on this path */ }

const outcome = composed.dryRun ? 'dry_run' : composed.circuitBreaker.open ? 'blocked_by_circuit_breaker' : composed.syncToHubspot ? 'synced' : 'sync_disabled';
const summary = { outcome, ...composed.runStats, plannedUpdates: composed.counts.updates, hubspotWrites: writes, circuitBreaker: composed.circuitBreaker, finishedAt: new Date().toISOString() };
console.log(`[social-enrichment-bridge] ${JSON.stringify(summary)}`);
return [{ json: summary }];
